{"code":"function chooseBin(item, remainingCapacities) {
  let best = -1;
  let bestSlack = Infinity;
  const n = remainingCapacities.length;
  for (let i = 0; i < n; i++) {
    const c = remainingCapacities[i];
    if (c < item) continue;
    const slack = c - item;
    if (slack >= 30) continue;
    if (slack < bestSlack) { bestSlack = slack; best = i; }
  }
  if (best !== -1) return best;
  let tight = -1;
  let tightSlack = Infinity;
  for (let i = 0; i < n; i++) {
    const c = remainingCapacities[i];
    if (c < item) continue;
    const slack = c - item;
    if (slack < tightSlack) { tightSlack = slack; tight = i; }
  }
  return tight;
}","hypothesis":"Reject bins with slack >= 30 first pass to avoid wasting large residuals; fall back to best-fit among the rest."}

